function search(){const q=$('#search-input').value.trim().toLowerCase(),results=q?searchItems.filter(x=>`${x.name} ${x.summary} ${x.group}`.toLowerCase().includes(q)):searchItems.filter(x=>['essay','map','layout','practice'].includes(x.href));$('#search-count').textContent=q?`${results.length} 个相关内容`:'从这些入口开始';$('#search-results').innerHTML=results.length?results.map(x=>`<a href="#/${x.href}"><span>${x.name}<small>${x.group}</small></span><p>${x.summary}</p>${arrow}</a>`).join(''):'<p class="no-results">还没有匹配的内容。试试“战略”“接纳”或“觉察”，也可以从三道全图寻找。</p>';}
$('#search-open').onclick=()=>{$('#search-dialog').showModal();search();$('#search-input').focus();};$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=search;$('#search-dialog').addEventListener('click',e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#menu-toggle').onclick=()=>{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'关闭导航':'打开导航');document.body.classList.toggle('menu-open',open);main.inert=open;$('.site-footer').inert=open;if(open)$('#mobile-nav a').focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#search-dialog').open){e.preventDefault();$('#search-dialog').close();return;}if(e.key==='Escape'&&!$('#mobile-nav').hidden){$('#menu-toggle').click();$('#menu-toggle').focus();}if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();$('#search-open').click();}});
document.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}const a=e.target.closest('a[href^="#/"]');if(a&&$('#search-dialog').open)$('#search-dialog').close();if(a&&a.hash===location.hash){scrollTo({top:0,behavior:'smooth'});if(!$('#mobile-nav').hidden)$('#menu-toggle').click();}});
$('.back-top').onclick=()=>scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
function updateHeader(){$('#header').classList.toggle('scrolled',scrollY>30);if(document.body.classList.contains('reading')){const total=Math.max(1,main.offsetHeight-innerHeight);document.documentElement.style.setProperty('--reading-progress',Math.min(100,Math.max(0,scrollY/total*100))+'%');}}
addEventListener('scroll',updateHeader,{passive:true});addEventListener('hashchange',()=>{if(!location.hash||location.hash.startsWith('#/'))route();});$('.skip-link').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});};route();
